 [("최소 거리",[r"거리 제곱의 미분 — 꺾인 점은 따로."]),("역함수 치환",[r"$dt=(1+2e^{2s})ds$."])],
 [("의도",['C1']),("$x\\ge0$로 축소",['C1']),("꺾인 점",['C1']),("$t>1$",['C1']),("치환 준비",['C2']),("적분 변환",['C3']),("계산",['C3']),("답",['C4','C5'])],
 [("꺾인 점",'C1',[r"$\psi'(0)\ge0$이면 $x\ge0$에서 증가."]),("$s=\\ln2$",'C2',[r"$e^{4s}+e^{2s}=20$ → $e^{2s}=4$."])],
 [("변형 · $d(k)^2=6$",[r"실수 $t$에 대하여 점 $(t,\,0)$과 곡선 $y=e^{|x|}$ 위의 점 사이의 거리의 최솟값을 $d(t)$라 하자. $\{d(k)\}^2=6$을 만족시키는 양수 $k$에 대하여 $\int_0^k\{d(t)\}^2dt=\frac qp$일 때, $p+q$의 값을 구하시오. (단, $p$와 $q$는 서로소인 자연수이다.)"],89,r"$e^{2s}=2$; $\frac43+\frac{61}{12}=\frac{77}{12}$.")],
